#!/usr/bin/env bash
# Regenerates the argument reference from pidsmaker/config/config.py, then builds the site.
# Run in an environment with PIDSMaker installed from source (the argument reference is
# generated by importing pidsmaker) and Zensical (Python >= 3.11).
set -e
cd "$(dirname "$0")"

python scripts/get_arguments.py        # docs/scripts/args/*.md

if ! command -v zensical >/dev/null 2>&1; then
  echo "zensical not found. It needs Python >= 3.11; install it with:"
  echo "  pip install zensical==0.1.3"
  exit 1
fi
zensical build --clean
